class Solution { fun numBusesToDestination(routes:Array<IntArray>,source:Int,target:Int):Int{if(source==target)return 0;val stopRoutes=mutableMapOf<Int,MutableList<Int>>();for(route in routes.indices)for(stop in routes[route])stopRoutes.getOrPut(stop){mutableListOf()}.add(route);val queue=java.util.ArrayDeque<Int>();val seenStops=mutableSetOf(source);val seenRoutes=BooleanArray(routes.size);queue.addLast(source);var buses=0;while(queue.isNotEmpty()){buses++;repeat(queue.size){val stop=queue.removeFirst();for(route in stopRoutes[stop].orEmpty())if(!seenRoutes[route]){seenRoutes[route]=true;for(next in routes[route]){if(next==target)return buses;if(seenStops.add(next))queue.addLast(next)}}}};return -1} }
